from copy import deepcopy
from work import evaluate
p={'defaults':{'b':True,'i':3,'s':'x'},'types':{'b':'boolean','i':'integer','s':'string'},'null_resets':True,'environment':True}
p_before=deepcopy(p)
r={'layers':[{'b':False,'i':0,'s':''},{'i':None}],'environment':{'i':'-7'}}
r_before=deepcopy(r)
assert evaluate(r,p)=={'ok':True,'config':{'b':False,'i':-7,'s':''},'error':None}
assert p==p_before and r==r_before
assert evaluate({'layers':[{'i':'bad'}],'environment':{'i':'9'}},p)['ok'] is True
print('immutability and final-validation checks passed')
